frappe.ui.form.on('User', {
    refresh: function(frm) {
        setTimeout(function() {
            hide_roles();
            filter_modules();
            hide_bulk_buttons();
        }, 700);
    }
});

function hide_roles() {
    const blacklist = ['System Manager', 'Script Manager'];

    blacklist.forEach(function(role) {
        $(`[data-fieldname="roles_html"] input[data-unit="${role}"]`)
            .closest('div.unit-checkbox')
            .hide();
    });
}

function filter_modules() {
    const whitelist = [
        'Accounts',
        'Buying',
        'Selling',
        'Stock',
        'IIB'
    ];

    $('[data-fieldname="modules_html"] div.unit-checkbox').each(function() {
        const unit = $(this).find('input').data('unit');
        if (!whitelist.includes(unit)) {
            $(this).hide();
        }
    });
}

function hide_bulk_buttons() {
    $('div.bulk-select-options').hide();
}

frappe.ui.form.on('Production Plan', {
    get_sales_orders: function(frm) {
        frappe.call({
            method: 'get_open_sales_orders',
            doc: frm.doc,
            callback: function(r) {
                refresh_field('sales_orders');

                frm.clear_table('prod_plan_references');
                frappe.call({
                    method: 'get_items',
                    freeze: true,
                    doc: frm.doc,
                    callback: function() {
                        refresh_field('po_items');

                        frm.dirty();
                        frappe.call({
                            method: 'get_sub_assembly_items',
                            freeze: true,
                            doc: frm.doc,
                            callback: function() {
                                refresh_field('sub_assembly_items');
                            }
                        });
                    }
                });
            }
        });
    }
});

frappe.ui.form.on('Sales Order', {
    refresh: function(frm) {
        set_item_query(frm);
    },
    customer: function(frm) {
        set_item_query(frm);
    }
});

function set_item_query(frm) {
    frm.set_query('item_code', 'items', function() {
        return {
            query: 'iib.overrides.sales_order.item_query',
            filters: {
                customer: frm.doc.customer || ''
            }
        };
    });
}

frappe.ui.form.on('SO Batch', {
    onload: function(frm) {
        restrict_transaction_date_to_today(frm);
    },
    refresh: function(frm) {
        restrict_transaction_date_to_today(frm);
    },
    customer: function(frm) {
        if (!frm.doc.customer) return;
        frappe.db.get_value('Customer', frm.doc.customer, ['default_currency', 'payment_terms', 'custom_self_kurs'])
            .then(function(r) {
                if (!r.message) return;
                if (r.message.default_currency) {
                    frm.set_value('currency', r.message.default_currency);
                }
                if (r.message.payment_terms) {
                    frm.set_value('payment_terms_template', r.message.payment_terms);
                }
                frm._self_kurs = r.message.custom_self_kurs || 0;
            });
    },
    currency: function(frm) {
        if (!frm.doc.currency) return;
        let company_currency = frappe.defaults.get_global_default('currency');
        if (frm.doc.currency === company_currency) {
            frm.set_value('conversion_rate', 1.0);
            return;
        }
        if (frm._self_kurs) {
            frm.set_value('conversion_rate', frm._self_kurs);
            return;
        }
        frappe.call({
            method: 'erpnext.setup.utils.get_exchange_rate',
            args: {
                from_currency: frm.doc.currency,
                to_currency: company_currency,
                transaction_date: frm.doc.transaction_date || frappe.datetime.get_today()
            },
            callback: function(r) {
                if (r.message) frm.set_value('conversion_rate', r.message);
            }
        });
    }
});

// Child table: map 0 → Set, 1 → Pcs for set_or_pcs column (supports paste)
frappe.ui.form.on('SO Batch Item', {
    delivery_date: function(frm, cdt, cdn) {
        validate_item_delivery_date(frm, cdt, cdn);
    },
    set_or_pcs: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        let val = String(row.set_or_pcs).trim();
        if (val === '1') {
            frappe.model.set_value(cdt, cdn, 'set_or_pcs', 'Set');
        } else if (val === '2') {
            frappe.model.set_value(cdt, cdn, 'set_or_pcs', 'Pcs');
        }
    }
});
function restrict_transaction_date_to_today(frm) {
    frm.fields_dict['transaction_date'].datepicker?.update({
        minDate: new Date(frappe.datetime.get_today()),
    });
}

function validate_item_delivery_date(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    if (!row.delivery_date) return;
    if (frm.doc.transaction_date && row.delivery_date < frm.doc.transaction_date) {
        frappe.model.set_value(cdt, cdn, 'delivery_date', '');
        frappe.throw(__('Row ' + row.idx + ': Delivery Date cannot be before Transaction Date.'));
    }
    if (row.po_date && row.delivery_date < row.po_date) {
        frappe.model.set_value(cdt, cdn, 'delivery_date', '');
        frappe.throw(__('Row ' + row.idx + ': Delivery Date cannot be before PO Date.'));
    }
}
